package com.sungwoo.pressplanning.scanner;

import android.util.Base64;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.zip.GZIPInputStream;

/** Embedded, offline-capable production report prototype. */
final class ProductionReportHtml {
    private static final String GZIP_BASE64 =
            "" +
            "" +
            "";

    private ProductionReportHtml() { }

    static String get() {
        byte[] compressed = Base64.decode(GZIP_BASE64, Base64.DEFAULT);
        try (GZIPInputStream input = new GZIPInputStream(new ByteArrayInputStream(compressed));
             ByteArrayOutputStream output = new ByteArrayOutputStream()) {
            byte[] buffer = new byte[4096];
            int count;
            while ((count = input.read(buffer)) != -1) {
                output.write(buffer, 0, count);
            }
            return new String(output.toByteArray(), StandardCharsets.UTF_8);
        } catch (IOException exception) {
            throw new IllegalStateException("No se pudo abrir el reporte local", exception);
        }
    }
}
